class Solution:
    def maxScore(self, cardPoints: list[int], k: int) -> int:
        n = len(cardPoints)
        window_size = n - k
        cur_sum = sum(cardPoints[:window_size])
        min_sum = cur_sum
        for i in range(window_size, n):
            cur_sum += cardPoints[i] - cardPoints[i - window_size]
            min_sum = min(min_sum, cur_sum)
        return sum(cardPoints) - min_sum

#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    int maxScore(std::vector<int>& cardPoints, int k) {
        int n = cardPoints.size();
        int windowSize = n - k;
        int curSum = 0;
        for (int i = 0; i < windowSize; ++i) curSum += cardPoints[i];
        int minSum = curSum;
        for (int i = windowSize; i < n; ++i) {
            curSum += cardPoints[i] - cardPoints[i - windowSize];
            minSum = std::min(minSum, curSum);
        }
        int totalSum = std::accumulate(cardPoints.begin(), cardPoints.end(), 0);
        return totalSum - minSum;
    }
};

class Solution {
    public int maxScore(int[] cardPoints, int k) {
        int n = cardPoints.length;
        int windowSize = n - k;
        int curSum = 0, totalSum = 0;
        for (int x : cardPoints) totalSum += x;
        for (int i = 0; i < windowSize; i++) curSum += cardPoints[i];
        int minSum = curSum;
        for (int i = windowSize; i < n; i++) {
            curSum += cardPoints[i] - cardPoints[i - windowSize];
            minSum = Math.min(minSum, curSum);
        }
        return totalSum - minSum;
    }
}

